class StickerLabel(QLabel):
    # Keep sticker clicks from becoming window drags. Double-click is handled by TodoV2.eventFilter.
    def mousePressEvent(self,event): event.accept()
    def mouseReleaseEvent(self,event): event.accept()
    def mouseDoubleClickEvent(self,event):
        event.ignore()  # lets the installed event filter own the swap consistently


PEN_CLIP_ORIGINAL_PNG_B64 = ''


class PenClipButton(QPushButton):
    """Render the supplied transparent PNG without editing its source pixels."""
    def __init__(self,parent=None):
        super().__init__(parent)
        self.setFixedSize(86,202)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setToolTip('다이어리 열기')
        self.setStyleSheet('border:none;background:transparent;')
        self.original=QPixmap()
        self.original.loadFromData(base64.b64decode(PEN_CLIP_ORIGINAL_PNG_B64))

    def paintEvent(self,event):
        p=QPainter(self)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        target=self.original.size()
        target.scale(self.size(),Qt.AspectRatioMode.KeepAspectRatio)
        x=(self.width()-target.width())//2
        p.drawPixmap(QRect(x,0,target.width(),target.height()),self.original)
        p.end()


class MinimalCheckBox(QCheckBox):
    """Small square check matching the legal pad."""
    def __init__(self,parent=None):
        super().__init__(parent)
        self.setFixedSize(19,19)
        self.setCursor(Qt.CursorShape.PointingHandCursor)

    def paintEvent(self,event):
        p=QPainter(self);p.setRenderHint(QPainter.RenderHint.Antialiasing,False)
        p.setPen(QPen(QColor('#4F4A35'),1))
        p.setBrush(QColor('#4F4A35') if self.isChecked() else Qt.BrushStyle.NoBrush)
        p.drawRect(2,2,14,14)
        if self.isChecked():
            p.setPen(QPen(QColor('white'),2))
            p.drawLine(5,9,8,12);p.drawLine(8,12,14,6)
        p.end()


class DiaryEntryEdit(QLineEdit):
    def bind_checkbox(self,check,spacer):
        self._entry_check=check
        self._entry_spacer=spacer
        self.textChanged.connect(self._update_checkbox)
        self._update_checkbox()

    def _update_checkbox(self):
        visible=bool(self.text().strip()) or self.hasFocus()
        self._entry_check.setVisible(visible)
        self._entry_spacer.setVisible(not visible)

    def focusInEvent(self,event):
        super().focusInEvent(event)
        if hasattr(self,'_entry_check'):self._update_checkbox()

    def focusOutEvent(self,event):
        super().focusOutEvent(event)
        if hasattr(self,'_entry_check'):self._update_checkbox()


class DiaryDayRow(QFrame):
    """Draw separators only under the entry area, away from weekday labels."""
    def paintEvent(self,event):
        super().paintEvent(event)
        p=QPainter(self)
        p.setPen(QPen(QColor('#d5d5d5'),1))
        p.drawLine(0,self.height()-1,max(0,self.width()-3),self.height()-1)
        p.end()


