    def apply_diary_scale(self,scale,save=True):
        self.diary_scale=scale
        content_font=app_font(max(9,round(13*scale)),QFont.Weight.Normal,ui_scale=False)
        self.setFont(content_font)
        self.scroll.setFont(content_font)
        self.week_bar.setFont(content_font)
